function validate([words, letters, score]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 14) return 'words needs 1 to 14 entries.';
  if (words.some(w => typeof w !== 'string' || w.length < 1 || w.length > 15 || !/^[a-z]+$/.test(w))) return 'Each word has 1 to 15 lowercase letters.';
  if (!Array.isArray(letters) || letters.length < 1 || letters.length > 100) return 'letters needs 1 to 100 characters.';
  if (letters.some(c => typeof c !== 'string' || !/^[a-z]$/.test(c))) return 'Each entry of letters is one lowercase letter.';
  if (!Array.isArray(score) || score.length !== 26) return 'score needs exactly 26 values.';
  if (score.some(v => !Number.isInteger(v) || v < 0 || v > 10)) return 'Each score is an integer from 0 to 10.';
  return null;
}

