function maxScoreWords(words, letters, score) {
  // Try every subset of words as a bitmask and check its letter totals against the pool.
  const pool = {};
  for (const c of letters) pool[c] = (pool[c] || 0) + 1;
  let answer = 0;
  for (let mask = 0; mask < (1 << words.length); mask++) {
    const need = {};
    let value = 0;
    for (let i = 0; i < words.length; i++) {
      if (!(mask & (1 << i))) continue;
      for (const c of words[i]) {
        need[c] = (need[c] || 0) + 1;
        value += score[c.charCodeAt(0) - 97];
      }
    }
    if (Object.keys(need).every(c => need[c] <= (pool[c] || 0))) answer = Math.max(answer, value);
  }
  return answer;
}

