function generate(rand, size) {
  const large = size === 'large';
  const alphabet = large ? 6 + Math.floor(rand() * 21) : 2 + Math.floor(rand() * 4);
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * alphabet));
  const wordCount = large ? 14 : 1 + Math.floor(rand() * 6);
  const words = Array.from({ length: wordCount }, () => {
    const length = 1 + Math.floor(rand() * (large ? 15 : 4));
    return Array.from({ length }, letter).join('');
  });
  const letterCount = large ? 30 + Math.floor(rand() * 71) : 1 + Math.floor(rand() * 10);
  const letters = Array.from({ length: letterCount }, letter);
  const score = Array.from({ length: 26 }, () => Math.floor(rand() * 11));
  return [words, letters, score];
}
